<?php
require dirname(__DIR__).'/vendor/autoload.php';use app\services\CatalogReview as Q;
if(PHP_OS_FAMILY!=='Windows')throw new RuntimeException('Local test only');$c=require dirname(__DIR__).'/config/config_db.php';if(!preg_match('/host=(?:localhost|127\.0\.0\.1)(?:;|$)/',$c['dsn']))throw new RuntimeException('Local DB only');$db=new PDO($c['dsn'],$c['user'],$c['pass'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);Q::install($db);$repo=new Q($db);$ids=[];
function reviewDbCheck($ok,$message){if(!$ok)throw new RuntimeException($message);}
$before=$db->query('SELECT * FROM product WHERE id=1')->fetch(PDO::FETCH_ASSOC);$q=$db->prepare("INSERT INTO catalog_review_issue(product_id,issue_key,category,origin_note,status,review_comment,updated_by,created_at,updated_at) VALUES(1,?,'test','Test','deferred','',1,NOW(),NOW())");$key='test-'.bin2hex(random_bytes(8));$q->execute([$key]);$id=(int)$db->lastInsertId();
try{$repo->update($id,1,'resolved','Verified marking','test-document',1);$r=$db->query('SELECT * FROM catalog_review_issue WHERE id='.$id)->fetch(PDO::FETCH_ASSOC);reviewDbCheck($r['status']==='resolved'&&(int)$r['version']===2,'Saved status and version');$bad=false;try{$repo->update($id,1,'open','','',1);}catch(RuntimeException $e){$bad=true;}reviewDbCheck($bad,'Stale editor rejected');reviewDbCheck((int)$db->query('SELECT COUNT(*) FROM catalog_review_event WHERE issue_id='.$id)->fetchColumn()===1,'History preserved');reviewDbCheck($before===$db->query('SELECT * FROM product WHERE id=1')->fetch(PDO::FETCH_ASSOC),'Product untouched');$list=$repo->listing('resolved');reviewDbCheck($list['total']>=1,'Filters list saved review');echo "Catalog review DB: atomic save, history, concurrent edit protection, filtering and product isolation OK\n";}finally{$db->exec('DELETE FROM catalog_review_event WHERE issue_id='.$id);$db->exec('DELETE FROM catalog_review_issue WHERE id='.$id);}
